  <script>(function(){var g=document.currentScript.previousElementSibling,t=g.querySelector('.mkk-detail-toggle'),e=g.querySelector('.mkk-detail-edge');
   function set(cls,btn,on,openTitle,closeTitle,key,save){g.classList.toggle(cls,on);btn.setAttribute('aria-expanded',on?'false':'true');btn.title=on?openTitle:closeTitle;if(save)try{localStorage.setItem(key,on?'1':'0');}catch(x){}}
   function body(on,s){set('is-collapsed',t,on,'Tampilkan detail','Sembunyikan detail','mkk-detail-collapsed',s);}
   function side(on,s){set('is-hidden',e,on,'Tampilkan panel detail','Sembunyikan panel detail','mkk-detail-hidden',s);}
   try{body(localStorage.getItem('mkk-detail-collapsed')==='1');side(localStorage.getItem('mkk-detail-hidden')==='1');}catch(x){}
   t.addEventListener('click',function(){var on=!g.classList.contains('is-collapsed');if(!on&&g.classList.contains('is-hidden'))side(false,1);body(on,1);});
   e.addEventListener('click',function(){side(!g.classList.contains('is-hidden'),1);});})();</script>
