<script>document.addEventListener('click',function(e){var b=e.target.closest('[data-copy]');if(!b)return;var el=document.querySelector(b.getAttribute('data-copy'));if(!el)return;el.select();navigator.clipboard?navigator.clipboard.writeText(el.value):document.execCommand('copy');});</script>
